update wx_mp_user
subscribe = #{subscribe}, subscribe_time = #{subscribeTime}, unsubscribe_time = #{unsubscribeTime}, nickname = #{nickname}, avatar = #{avatar},
where id = #{id}

mapper.select:
select * from wx_mp_template_msg
where status = #{status} and date(create_time) < curdate()
order by id asc limit #{limit}

select l.*, p.deduct_tax as product_deduct_tax, p.up_channel as product_up_channel
from jonlink_insurance_ledger l
left join jonlink_product p on l.product_id = p.id

    and l.policy_no like concat('%', #{policyNo}, '%')
    and l.channel_name like concat('%', #{channelName}, '%')
    and l.applicant like concat('%', #{applicant}, '%')
    and l.up_settle_status = #{upSettleStatus}
    and l.down_settle_status = #{downSettleStatus}
    and l.ledger_date >= #{beginTime}
    and l.ledger_date <= #{endTime}

order by l.id desc

select ${column} as name, count(*) as value
from ${table}
where ${column} is not null and ${column} != ''
group by ${column}

mapper.update:
update jonlink_insurance_ledger


        up_settle_status = #{status}, up_settle_no = #{settleNo}
        down_settle_status = #{status}, down_settle_no = #{settleNo}


where id = #{id}

